#!/usr/bin/env bash
# Regenerates palette.nix from a seed colour, with the scheme the hecate shell
# uses for its own colours (matugen, tonal spot, dark).
#   theme/update-palette.sh [#rrggbb]
set -euo pipefail

cd "$(dirname "$0")"
seed="${1:-$(sed -n 's/^  seed = "\(#[0-9a-fA-F]\{6\}\)";$/\1/p' palette.nix 2>/dev/null || true)}"
seed="${seed:-#ff47c8}"

matugen=(matugen)
command -v matugen >/dev/null || matugen=(nix run nixpkgs#matugen --)

"${matugen[@]}" color hex "$seed" --mode dark --type scheme-tonal-spot --json hex --dry-run \
    | jq -r --arg seed "$seed" '
        "# Generated by theme/update-palette.sh. Material You (tonal spot, dark) roles,\n# named like the hecate shell'"'"'s generated colors.json.\n{\n  seed = \"\($seed)\";\n  colors = {",
        (.colors | to_entries | sort_by(.key)[] | "    \(.key) = \"\(.value.dark.color)\";"),
        "  };\n}"
    ' > palette.nix
